import { existsSync, readFileSync } from "node:fs"
import { join } from "node:path"
import { parseJsonStrict, parseSuiteManifest } from "@terminfo/run-parser"

/**
 * Per-row catalogue entry hashes for suite manifests written before manifests recorded them (33587, @cto d7ad1307,
 * d805d1af). Generated by scripts/generate-legacy-entry-hashes.ts, which refuses unless a checkout of the placed runs'
 * own sourceRevision recomputes the suite id. Read only through `suiteEntryHashes`, the site's per-row join test
 * (app-cells.ts). It sits outside the suite-hash inputs, so it never moves a suite id. It shrinks to nothing as those
 * runs are replaced, and is then deleted with its generator (legacy-entry-hashes.test.ts fails on a stale entry).
 */
export const LEGACY_ENTRY_HASHES_FILE = "content/legacy-entry-hashes.json"

export type LegacyEntryHashes = Record<
  string,
  { sourceRevision: string; generatedBy: string; generatedOn: string; catalogEntrySha256: Record<string, string> }
>

export function loadLegacyEntryHashes(contentDir: string): LegacyEntryHashes {
  const path = join(contentDir, "legacy-entry-hashes.json")
  if (!existsSync(path)) return {}
  const value = parseJsonStrict(path, readFileSync(path, "utf8"))
  if (value === null || typeof value !== "object" || Array.isArray(value)) throw new Error(`${path}: not an object`)
  const isRecord = (item: unknown): item is Record<string, unknown> =>
    item !== null && typeof item === "object" && !Array.isArray(item)
  for (const [suiteId, entry] of Object.entries(value as Record<string, unknown>)) {
    const ok =
      isRecord(entry) &&
      typeof entry.sourceRevision === "string" &&
      typeof entry.generatedBy === "string" &&
      typeof entry.generatedOn === "string" &&
      isRecord(entry.catalogEntrySha256) &&
      Object.values(entry.catalogEntrySha256).every((hash) => typeof hash === "string") &&
      Object.keys(entry).length === 4
    if (!ok) {
      throw new Error(
        `${path}: suite ${suiteId} needs exactly sourceRevision, generatedBy, generatedOn, catalogEntrySha256`,
      )
    }
  }
  return value as LegacyEntryHashes
}

/**
 * Each suite's per-row catalogue entry hashes: the suite manifest's own `catalogEntrySha256`, or, for a manifest
 * written before it, the reconstructed row in LEGACY_ENTRY_HASHES_FILE. A suite listed there whose manifest records
 * its own hashes throws: one suite never has two answers. Returns undefined for a suite with neither, which the
 * join reads as a refusal by name, never as a match.
 */
export function suiteEntryHashes(
  contentDir: string,
): (suiteId: string) => Readonly<Record<string, string>> | undefined {
  const legacy = loadLegacyEntryHashes(contentDir)
  const memo = new Map<string, Readonly<Record<string, string>> | undefined>()
  return (suiteId) => {
    if (memo.has(suiteId)) return memo.get(suiteId)
    const path = join(contentDir, "suites", `${suiteId}.json`)
    const recorded = existsSync(path)
      ? parseSuiteManifest(path, readFileSync(path, "utf8")).catalogEntrySha256
      : undefined
    if (recorded !== undefined && legacy[suiteId] !== undefined) {
      throw new Error(
        `${LEGACY_ENTRY_HASHES_FILE}: suite ${suiteId} is listed but ${path} records its own entry hashes`,
      )
    }
    const hashes = recorded ?? legacy[suiteId]?.catalogEntrySha256
    memo.set(suiteId, hashes)
    return hashes
  }
}
